<template><section><div class="rounded-3xl bg-slate-950 px-6 py-12 text-white md:px-12"><p class="text-sm font-bold uppercase tracking-[.2em] text-indigo-300">Company catalog · real inventory</p><h1 class="mt-3 max-w-3xl text-4xl font-black md:text-6xl">Shop products. Choose variants. Share and earn.</h1><p class="mt-5 max-w-xl text-slate-300">Products are organized by category and brand, with stock managed across company warehouses.</p></div><div class="mt-7 flex gap-3"><input v-model="search" @keyup.enter="load" class="flex-1 rounded-xl border bg-white px-4 py-3" placeholder="Search products…"/><select v-model="category" @change="load" class="rounded-xl border bg-white px-4 py-3"><option value="">All categories</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div v-if="loading" class="py-20 text-center">Loading catalog…</div><div v-else class="mt-7 grid gap-5 sm:grid-cols-2 lg:grid-cols-4"><article v-for="p in products" :key="p.id" class="overflow-hidden rounded-2xl border bg-white"><RouterLink :to="'/products/'+p.slug"><div class="aspect-square bg-slate-100"><img v-if="p.imageUrl" :src="p.imageUrl" class="h-full w-full object-cover"/></div><div class="p-4"><div class="flex items-center justify-between gap-2"><h2 class="font-bold">{{p.name}}</h2><span v-if="p.brand" class="text-xs text-slate-400">{{p.brand.name}}</span></div><p class="mt-2 text-lg font-black text-indigo-600">{{Number(minPrice(p)).toLocaleString()}} {{p.currency||'ETB'}}</p><p class="mt-1 text-xs text-slate-400">{{p.variants?.length||0}} variant{{p.variants?.length===1?'':'s'}}</p></div></RouterLink><RouterLink :to="'/products/'+p.slug" class="m-4 mt-0 block rounded-xl bg-slate-950 py-3 text-center font-bold text-white">Choose options</RouterLink></article></div></section></template>
<script>import api from'../services/api';export default{data(){return{products:[],categories:[],search:'',category:'',loading:true}},async mounted(){await this.load()},methods:{async load(){this.loading=true;try{const[p,c]=await Promise.all([api.get('/products',{params:{q:this.search,categoryId:this.category||undefined}}),api.get('/categories')]);this.products=p.data.data||[];this.categories=c.data.data||[]}finally{this.loading=false}},minPrice(p){return Math.min(...(p.variants||[]).map(v=>Number(v.price??p.price)).filter(Number.isFinite),Number(p.price))}}}</script>